import os
from typing import List, Dict, Optional
from google.cloud import texttospeech


def list_voices_for_locale(locale: str, gender: Optional[str] = None) -> List[Dict[str, object]]:
    client = texttospeech.TextToSpeechClient()

    response = client.list_voices(language_code=locale)

    gender_map = {
        "MALE": texttospeech.SsmlVoiceGender.MALE,
        "FEMALE": texttospeech.SsmlVoiceGender.FEMALE,
        "NEUTRAL": texttospeech.SsmlVoiceGender.NEUTRAL,
    }
    requested_gender = gender_map.get(gender.upper()) if gender else None

    voices = []
    for voice in response.voices:
        if requested_gender is not None and voice.ssml_gender != requested_gender:
            continue
        voices.append(
            {
                "name": voice.name,
                "language_codes": list(voice.language_codes),
                "ssml_gender": texttospeech.SsmlVoiceGender(voice.ssml_gender).name,
                "natural_sample_rate_hertz": voice.natural_sample_rate_hertz,
            }
        )

    return sorted(voices, key=lambda v: v["name"])


def select_voice_for_locale(locale: str, gender: Optional[str] = None) -> Dict[str, object]:
    voices = list_voices_for_locale(locale, gender=gender)
    if not voices:
        raise ValueError(f"No Google Cloud Text-to-Speech voices found for locale={locale!r} gender={gender!r}")
    return voices[0]


if __name__ == "__main__":
    target_locale = os.getenv("TARGET_LOCALE", "en-US")
    target_gender = os.getenv("TARGET_GENDER")
    print(select_voice_for_locale(target_locale, target_gender))
